-- lovable-cron-fallback-reviewed: Known future publishing deadlines need persisted transitions without browsers; arm on scheduled posts and unschedule after drain, maximum one minute delay.
ALTER TABLE public.content_posts ADD COLUMN IF NOT EXISTS scheduled_at timestamptz, ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public', ADD COLUMN IF NOT EXISTS og_title text, ADD COLUMN IF NOT EXISTS og_description text, ADD COLUMN IF NOT EXISTS cta_label text, ADD COLUMN IF NOT EXISTS cta_url text, ADD COLUMN IF NOT EXISTS created_by uuid, ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1;
CREATE TABLE public.blog_staff (user_id uuid PRIMARY KEY,role text NOT NULL CHECK(role IN ('editor','writer')));
GRANT SELECT ON public.blog_staff TO authenticated; GRANT ALL ON public.blog_staff TO service_role;
ALTER TABLE public.blog_staff ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff reads own role" ON public.blog_staff FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role('admin'));
CREATE FUNCTION public.blog_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_role('admin') THEN 'admin' ELSE (SELECT role FROM public.blog_staff WHERE user_id=auth.uid()) END $$;
REVOKE ALL ON FUNCTION public.blog_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.blog_role() TO authenticated;
CREATE TABLE public.blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',image_url text,seo_title text,meta_description text,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.blog_categories TO authenticated; GRANT ALL ON public.blog_categories TO service_role;
ALTER TABLE public.blog_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public categories" ON public.blog_categories FOR SELECT TO anon,authenticated USING(NOT archived);
CREATE POLICY "CMS manages categories" ON public.blog_categories FOR ALL TO authenticated USING(public.blog_role() IN ('admin','editor')) WITH CHECK(public.blog_role() IN ('admin','editor'));
CREATE TABLE public.blog_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES public.content_posts(id) ON DELETE CASCADE,snapshot jsonb NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_revisions TO authenticated; GRANT ALL ON public.blog_revisions TO service_role;
ALTER TABLE public.blog_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "CMS reads revisions" ON public.blog_revisions FOR SELECT TO authenticated USING(public.blog_role() IN ('admin','editor') OR (public.blog_role()='writer' AND EXISTS(SELECT 1 FROM public.content_posts p WHERE p.id=post_id AND p.created_by=auth.uid())));
CREATE TABLE public.blog_redirects (old_slug text PRIMARY KEY,post_id uuid NOT NULL REFERENCES public.content_posts(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_redirects TO anon,authenticated; GRANT ALL ON public.blog_redirects TO service_role;
ALTER TABLE public.blog_redirects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published redirects only" ON public.blog_redirects FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.content_posts p WHERE p.id=post_id AND p.status='published' AND p.visibility='public' AND p.published_at<=now()));
CREATE TABLE public.blog_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id),title text NOT NULL DEFAULT 'Xellvio Blog',description text NOT NULL DEFAULT 'Practical ideas for better customer conversations.',cta_label text NOT NULL DEFAULT 'Create your Xellvio account',cta_url text NOT NULL DEFAULT '/auth?mode=signup',newsletter_enabled boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.blog_settings TO anon,authenticated; GRANT INSERT,UPDATE ON public.blog_settings TO authenticated; GRANT ALL ON public.blog_settings TO service_role;
ALTER TABLE public.blog_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public blog settings" ON public.blog_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin manages blog settings" ON public.blog_settings FOR ALL TO authenticated USING(public.blog_role()='admin') WITH CHECK(public.blog_role()='admin');
CREATE TABLE public.blog_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,consent_text text NOT NULL,consented_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL DEFAULT '/blog',status text NOT NULL DEFAULT 'subscribed');
GRANT SELECT ON public.blog_subscriptions TO authenticated; GRANT ALL ON public.blog_subscriptions TO service_role;
ALTER TABLE public.blog_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "CMS reads subscriptions" ON public.blog_subscriptions FOR SELECT TO authenticated USING(public.blog_role() IN ('admin','editor'));
CREATE TABLE public.blog_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid,action text NOT NULL,actor_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_audit TO authenticated; GRANT ALL ON public.blog_audit TO service_role;
ALTER TABLE public.blog_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "CMS reads audit" ON public.blog_audit FOR SELECT TO authenticated USING(public.blog_role() IN ('admin','editor'));
ALTER TABLE public.media_assets ADD COLUMN IF NOT EXISTS blog_asset boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS alt_text text NOT NULL DEFAULT '';
CREATE POLICY "CMS media" ON public.media_assets FOR ALL TO authenticated USING(blog_asset AND public.blog_role() IN ('admin','editor','writer')) WITH CHECK(blog_asset AND public.blog_role() IN ('admin','editor','writer'));
GRANT SELECT ON public.content_posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.content_posts TO authenticated; GRANT ALL ON public.content_posts TO service_role;
DROP POLICY "Published content is public" ON public.content_posts;
CREATE POLICY "Published content is public" ON public.content_posts FOR SELECT TO anon,authenticated USING(status='published' AND visibility='public' AND published_at<=now());
CREATE POLICY "CMS staff reads posts" ON public.content_posts FOR SELECT TO authenticated USING(public.blog_role() IN ('admin','editor') OR (public.blog_role()='writer' AND created_by=auth.uid()));
CREATE POLICY "CMS staff writes posts" ON public.content_posts FOR ALL TO authenticated USING(public.blog_role() IN ('admin','editor') OR (public.blog_role()='writer' AND created_by=auth.uid() AND status IN ('draft','in_review'))) WITH CHECK(public.blog_role() IN ('admin','editor') OR (public.blog_role()='writer' AND created_by=auth.uid() AND status IN ('draft','in_review')));
GRANT SELECT ON public.content_authors TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.content_authors TO authenticated;
CREATE POLICY "Published author profiles" ON public.content_authors FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.content_posts p WHERE p.author_id=content_authors.id AND p.status='published' AND p.visibility='public' AND p.published_at<=now()));
CREATE POLICY "CMS manages authors" ON public.content_authors FOR ALL TO authenticated USING(public.blog_role() IN ('admin','editor')) WITH CHECK(public.blog_role() IN ('admin','editor'));
GRANT SELECT ON public.content_events TO authenticated;
CREATE POLICY "CMS reads events" ON public.content_events FOR SELECT TO authenticated USING(public.blog_role() IN ('admin','editor'));
CREATE INDEX blog_published_idx ON public.content_posts(status,published_at DESC); CREATE INDEX blog_topic_idx ON public.content_posts(topic,status); CREATE INDEX blog_schedule_idx ON public.content_posts(scheduled_at) WHERE status='scheduled'; CREATE INDEX blog_revision_idx ON public.blog_revisions(post_id,created_at DESC); CREATE INDEX blog_event_idx ON public.content_events(created_at,slug,event_type);
CREATE FUNCTION public.blog_post_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r text; BEGIN
IF auth.role()='authenticated' THEN r:=public.blog_role(); IF r IS NULL THEN RAISE EXCEPTION 'CMS access required'; END IF; IF r='writer' AND (NEW.status NOT IN ('draft','in_review') OR (TG_OP='UPDATE' AND OLD.status NOT IN ('draft','in_review')) OR NEW.created_by IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Writers may only edit their own drafts'; END IF; END IF;
IF NEW.status IN ('published','scheduled') AND (btrim(NEW.title)='' OR btrim(NEW.body)='' OR (NEW.featured_image IS NOT NULL AND btrim(coalesce(NEW.image_alt,''))='')) THEN RAISE EXCEPTION 'Title, content and image alt text are required for publishing'; END IF;
IF NEW.status='scheduled' AND (NEW.scheduled_at IS NULL OR NEW.scheduled_at<=now()) THEN RAISE EXCEPTION 'Choose a future publishing time'; END IF;
IF TG_OP='UPDATE' THEN INSERT INTO public.blog_revisions(post_id,snapshot,created_by) VALUES(OLD.id,to_jsonb(OLD),auth.uid()); IF OLD.slug<>NEW.slug AND OLD.published_at IS NOT NULL THEN INSERT INTO public.blog_redirects(old_slug,post_id) VALUES(OLD.slug,OLD.id) ON CONFLICT(old_slug) DO UPDATE SET post_id=EXCLUDED.post_id; END IF; NEW.version:=OLD.version+1; END IF;
IF NEW.status='published' AND NEW.published_at IS NULL THEN NEW.published_at:=now(); END IF; NEW.updated_at:=now(); INSERT INTO public.blog_audit(post_id,action,actor_id,details) VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN 'created' ELSE NEW.status::text END,auth.uid(),jsonb_build_object('slug',NEW.slug)); RETURN NEW; END $$;
CREATE TRIGGER blog_post_guard BEFORE INSERT OR UPDATE ON public.content_posts FOR EACH ROW EXECUTE FUNCTION public.blog_post_guard();
CREATE FUNCTION public.blog_delete_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.blog_audit(post_id,action,actor_id,details) VALUES(OLD.id,'deleted',auth.uid(),jsonb_build_object('title',OLD.title,'slug',OLD.slug)); RETURN OLD; END $$;
CREATE TRIGGER blog_delete_audit BEFORE DELETE ON public.content_posts FOR EACH ROW EXECUTE FUNCTION public.blog_delete_audit();
CREATE FUNCTION public.blog_publish_due() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN UPDATE public.content_posts SET status='published',published_at=scheduled_at,scheduled_at=NULL WHERE status='scheduled' AND scheduled_at<=now(); GET DIAGNOSTICS n=ROW_COUNT; IF NOT EXISTS(SELECT 1 FROM public.content_posts WHERE status='scheduled') THEN PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname='blog-publish-due'; END IF; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.blog_publish_due() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.blog_publish_due() TO service_role;
CREATE FUNCTION public.blog_arm_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='scheduled' THEN PERFORM cron.schedule('blog-publish-due','* * * * *','SELECT public.blog_publish_due()'); ELSIF NOT EXISTS(SELECT 1 FROM public.content_posts WHERE status='scheduled') THEN PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname='blog-publish-due'; END IF; RETURN NEW; END $$;
CREATE TRIGGER blog_arm_schedule AFTER INSERT OR UPDATE ON public.content_posts FOR EACH ROW EXECUTE FUNCTION public.blog_arm_schedule();